package com.print.kiosk.service;
import com.print.kiosk.entity.*;import com.print.kiosk.repository.*;import com.print.kiosk.service.interfaces.FileCleanupService;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import java.math.BigDecimal;import java.time.LocalDateTime;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") class FileCleanupServiceIntegrationTest{@Autowired PrintRequestRepository requests;@Autowired PrintRequestFileRepository files;@Autowired FileCleanupService cleanup;@BeforeEach void clear(){files.deleteAll();requests.deleteAll();}@Test void deletesOnlyBinaryContentAndKeepsMetadata(){PrintRequest r=request();PrintRequestFile f=new PrintRequestFile();f.setPrintRequest(r);f.setOriginalFileName("a.pdf");f.setFileType(PrintFileType.PDF);f.setMimeType("application/pdf");f.setFileSizeBytes(3);f.setPageCount(1);f.setPhysicalSheetsPerCopy(1);f.setTotalPhysicalSheets(1);f.setCopies(1);f.setAppliedRate(new BigDecimal("2.00"));f.setSubtotal(new BigDecimal("2.00"));f.setCalculatedAt(LocalDateTime.now());f.setDeletionEligibleAt(LocalDateTime.now().minusMinutes(1));f.setFileData(new byte[]{1,2,3});f=files.saveAndFlush(f);assertEquals(1,cleanup.deleteEligibleFileContent());PrintRequestFile saved=files.findById(f.getId()).orElseThrow();assertNull(saved.getFileData());assertNotNull(saved.getBinaryDeletedAt());assertEquals("a.pdf",saved.getOriginalFileName());}private PrintRequest request(){PrintRequest r=new PrintRequest();r.setTrackingNumber("PR-CLEAN");r.setFullName("Cleanup");r.setRegistrationNumber("242-15-125");r.setUserType(UserType.STUDENT);r.setPrintColor(PrintColor.BLACK_AND_WHITE);r.setPrintingSide(PrintingSide.SINGLE_SIDED);r.setCopies(1);r.setStatus(PrintRequestStatus.COMPLETED);r.setPaymentStatus(PaymentStatus.PAID);r.setPricingConfigId(1L);r.setPricingRevision(1);r.setAppliedRate(new BigDecimal("2.00"));r.setTotalDocumentPages(1);r.setTotalPhysicalSheets(1);r.setTotalAmount(new BigDecimal("2.00"));r.setCalculatedAt(LocalDateTime.now());r.setExpiresAt(LocalDateTime.now().plusHours(1));return requests.saveAndFlush(r);}}